-- Create "health_checks" table
CREATE TABLE "health_checks" ("id" character varying NOT NULL, "org_id" character varying NOT NULL, "type" character varying NOT NULL, "port" bigint NOT NULL DEFAULT 0, "http_path" character varying NOT NULL DEFAULT '', "expected_status_min" bigint NOT NULL DEFAULT 0, "expected_status_max" bigint NOT NULL DEFAULT 0, "interval_seconds" bigint NOT NULL DEFAULT 0, "timeout_seconds" bigint NOT NULL DEFAULT 0, "unhealthy_threshold" bigint NOT NULL DEFAULT 0, "healthy_threshold" bigint NOT NULL DEFAULT 0, "route_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "health_checks_routes_route" FOREIGN KEY ("org_id", "route_id") REFERENCES "routes" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "health_checks_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "healthcheck_org_id_id" to table: "health_checks"
CREATE UNIQUE INDEX "healthcheck_org_id_id" ON "health_checks" ("org_id", "id");
